def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if budget <= 0:
        return 0.0

    if not alive:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water >= 1:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    aggressive_count = 0
    needy_count = 0
    rich_count = 0
    for oid, opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            rich_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            needy_count += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) >= DAILY_SALARY * 0.9:
                aggressive_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    units = supply / float(WATER_REQ)
    tight_supply = units < (len(alive) + 1)
    very_tight = units < len(alive)

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2
    if very_tight:
        urgency += 2
    elif tight_supply:
        urgency += 1
    if day >= 8:
        urgency += 1

    if urgency >= 5:
        target = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
    elif urgency >= 3:
        if aggressive_count > 0:
            target = max(DAILY_SALARY * 0.72, min(highest_prev + 1.5, DAILY_SALARY * 1.02))
        else:
            target = max(DAILY_SALARY * 0.58, avg_prev + 1.0)
    else:
        if aggressive_count >= 2 and hp > 4:
            target = DAILY_SALARY * 0.28
        elif tight_supply:
            target = max(DAILY_SALARY * 0.48, avg_prev * 0.75 + 1.0)
        else:
            target = DAILY_SALARY * 0.34

    if rich_count >= 2 and tight_supply and urgency <= 2:
        target *= 0.9
    if needy_count >= 2 and urgency >= 3:
        target *= 1.08

    reserve_days = max(0, 10 - day)
    soft_cap = budget
    if reserve_days > 0:
        reserve_buffer = reserve_days * DAILY_SALARY * 0.22
        soft_cap = max(0.0, budget - reserve_buffer)
        if urgency >= 4:
            soft_cap = budget

    bid = min(target, budget)
    if soft_cap > 0:
        bid = min(bid, max(soft_cap, DAILY_SALARY * 0.25 if urgency >= 3 else DAILY_SALARY * 0.15))

    if hp <= 2 or no_water >= 2:
        bid = max(bid, min(budget, DAILY_SALARY * 0.9))
    elif no_water >= 1 and tight_supply:
        bid = max(bid, min(budget, DAILY_SALARY * 0.7))

    if budget < DAILY_SALARY * 0.5:
        bid = min(bid, budget)
    bid = max(0.0, min(float(budget), float(bid)))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        cap = min(budget, DAILY_SALARY * 0.4)
        return max(0.0, cap)

    # Read yesterday bids to infer aggressiveness
    prev_bids = []
    prev_max_bid = 0.0
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b = float(b)
                prev_bids.append(b)
                if b > prev_max_bid:
                    prev_max_bid = b
            except Exception:
                pass

    # Supply pressure: if supply is near minimum, competition likely higher.
    # Convert supply to a coarse level.
    if supply <= float(MIN_SUPPLY):
        pressure = 1.0
    elif supply >= float(MAX_SUPPLY):
        pressure = 0.2
    else:
        # linear scale from 1.0 at MIN_SUPPLY to 0.2 at MAX_SUPPLY
        pressure = 1.0 - 0.8 * ((supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY)))

    # Base willingness to bid
    # If my HP is low or I have already missed water, increase bid.
    if hp <= 2.0 or no_water_days >= 1:
        base = DAILY_SALARY * (0.75 + 0.2 * pressure)
    elif hp <= 4.0:
        base = DAILY_SALARY * (0.55 + 0.2 * pressure)
    else:
        base = DAILY_SALARY * (0.45 + 0.15 * pressure)

    # Exploit trace: Cindy bid very high and survived; others with 0 budget/low hp suggest they can't sustain.
    # So we avoid matching extreme bids; only slightly react to the top bid unless it's near total salary.
    if prev_bids:
        if prev_max_bid >= DAILY_SALARY * 0.9:
            # Cindy-like aggression: don't chase fully; bid enough to beat weaker opponents.
            base = min(base, DAILY_SALARY * 0.65)
        else:
            # If top bid is moderate, nudge upward to outbid likely competitors.
            base = max(base, min(DAILY_SALARY * 0.6, prev_max_bid + 5.0))

    # Ensure we can afford it
    bid = min(budget, base)

    # Safety: if budget is tiny, still bid something to avoid starvation.
    if bid < 1.0:
        bid = min(budget, DAILY_SALARY * 0.15)

    # Clamp to non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 20.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    target_bid = avg_prev * 1.05
    return min(my_status['budget'], max(15.0, target_bid))
